<?php
declare(strict_types=1);
$b = $booking;
function booking_steps(int $active): void { ?>
<ol class="booking-steps" aria-label="Postęp rezerwacji">
<?php foreach ([1=>'Usługa',2=>'Pracownik',3=>'Data',4=>'Godzina',5=>'Potwierdzenie'] as $n=>$label): ?>
<li<?= $n === $active ? ' aria-current="step"' : '' ?> class="<?= $n < $active ? 'done' : '' ?>"><span><?= $n ?></span><?= e($label) ?></li>
<?php endforeach ?></ol><?php }
function reservation_card(array $row, string $target, array $extra = []): void { ?>
<article class="reservation-card"><div><p class="eyebrow"><?= e($row['reservation_date']) ?> · <?= e(substr($row['start_time'],0,5)) ?>–<?= e(substr($row['end_time'],0,5)) ?></p>
<h3><?= e($row['service_name']) ?></h3><p><?= e($row['company_name'] ?? $row['client_name'] ?? '') ?></p></div>
<div><span class="status status-<?= e($row['status']) ?>"><?= e(status_label($row['status'])) ?></span>
<a class="button secondary small" href="<?= e(route_url($target, ['id'=>$row['id']] + $extra)) ?>">Szczegóły</a></div></article><?php }
?>
<?php if (isset($b['error'])): ?>
<section class="page container"><h1>Nie można wykonać operacji</h1><div class="error-summary" role="alert"><?= e($b['error']) ?></div><a class="button" href="<?= url('companies') ?>">Wróć do katalogu</a></section>
<?php elseif ($route === 'companies'): $catalog=$b['catalog']; ?>
<section class="page container"><p class="eyebrow">Znajdź termin dla siebie</p><h1>Odkrywaj firmy</h1>
<form method="get" class="catalog-filters"><input type="hidden" name="route" value="companies"><label>Szukaj<input name="q" value="<?= e($catalog['filters']['q']) ?>" maxlength="120" placeholder="Nazwa lub opis"></label>
<label>Miasto<select name="city"><option value="">Wszystkie</option><?php foreach($catalog['cities'] as $city): ?><option<?= $city===$catalog['filters']['city']?' selected':'' ?>><?= e($city) ?></option><?php endforeach ?></select></label>
<label>Kategoria<select name="category_id"><option value="">Wszystkie</option><?php foreach($catalog['categories'] as $cat): ?><option value="<?= $cat['id'] ?>"<?= $cat['id']===$catalog['filters']['category_id']?' selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach ?></select></label><button class="button">Filtruj</button></form>
<?php if(!$catalog['rows']): ?><div class="empty-state"><h2>Brak pasujących firm</h2><p>Zmień filtry albo wróć później.</p></div><?php else: ?><div class="company-grid"><?php foreach($catalog['rows'] as $company): ?><article class="company-card">
<div class="company-logo"><?php if($company['logo_path']): ?><img src="<?= e(route_url('media',['name'=>$company['logo_path']])) ?>" alt="Logo <?= e($company['name']) ?>"><?php else: ?><?= e(mb_strtoupper(mb_substr($company['name'],0,2))) ?><?php endif ?></div>
<div><p class="eyebrow"><?= e($company['city']) ?></p><h2><?= e($company['name']) ?></h2><p><?= e($company['short_description']) ?></p><a class="button" href="<?= e(route_url('company/show',['id'=>$company['id']])) ?>">Zobacz ofertę</a></div></article><?php endforeach ?></div><?php endif ?>
<?php if($catalog['pages']>1): ?><nav class="pagination" aria-label="Strony"><?php for($p=1;$p<=$catalog['pages'];$p++): ?><a<?= $p===$catalog['page']?' aria-current="page"':'' ?> href="<?= e(route_url('companies',array_filter($catalog['filters'])+['page'=>$p])) ?>"><?= $p ?></a><?php endfor ?></nav><?php endif ?></section>
<?php elseif ($route === 'company/show'): $company=$b['company']; ?>
<section class="company-hero"><?php if($company['banner_path']): ?><img src="<?= e(route_url('media',['name'=>$company['banner_path']])) ?>" alt=""><?php endif ?><div class="container"><p class="eyebrow"><?= e($company['city']) ?></p><h1><?= e($company['name']) ?></h1><p><?= e($company['short_description']) ?></p></div></section>
<section class="page container"><div class="company-about"><div><h2>O firmie</h2><p><?= nl2br(e($company['description'])) ?></p></div><dl><div><dt>Adres</dt><dd><?= e($company['address']) ?></dd></div><div><dt>Telefon</dt><dd><?= e($company['phone']) ?></dd></div><div><dt>E-mail</dt><dd><?= e($company['email']) ?></dd></div></dl></div><h2>Usługi</h2>
<?php if(!$company['services']): ?><div class="empty-state">Firma nie ma obecnie aktywnych usług.</div><?php else: ?><div class="service-grid"><?php foreach($company['services'] as $service): ?><article class="service-card"><p class="eyebrow"><?= e($service['category_name']) ?></p><h3><?= e($service['name']) ?></h3><p><?= e($service['description']) ?></p><p><strong><?= (int)$service['duration_minutes'] ?> min · <?= e(money_pl($service['price'])) ?></strong></p><?php if($service['bookable']): ?><a class="button" href="<?= e(route_url('booking/employees',['service_id'=>$service['id']])) ?>">Wybierz usługę</a><?php else: ?><span class="muted">Brak dostępnych pracowników</span><?php endif ?></article><?php endforeach ?></div><?php endif ?></section>
<?php elseif ($route === 'booking/employees'): $service=$b['service']; ?>
<section class="page container"><?php booking_steps(2) ?><p class="eyebrow"><?= e($service['company_name']) ?></p><h1>Wybierz pracownika</h1><p><?= e($service['name']) ?> · <?= (int)$service['duration_minutes'] ?> min · <?= e(money_pl($service['price'])) ?></p>
<div class="employee-grid"><?php foreach($service['employees'] as $employee): ?><article class="feature-card"><span class="avatar"><?= e(mb_strtoupper(mb_substr($employee['name'],0,1))) ?></span><h2><?= e($employee['name']) ?></h2><p><?= e($employee['description']) ?></p><a class="button" href="<?= e(route_url('booking/date',['service_id'=>$service['id'],'employee_id'=>$employee['id']])) ?>">Wybierz</a></article><?php endforeach ?></div></section>
<?php elseif ($route === 'booking/date'): $ctx=$b['context']; ?>
<section class="page container"><?php booking_steps(3) ?><h1>Wybierz datę</h1><div class="booking-summary"><strong><?= e($ctx['service_name']) ?></strong><span><?= e($ctx['employee_name']) ?></span><span><?= e($ctx['company_name']) ?></span></div>
<form action="<?= url('booking/time') ?>" method="get" class="date-form" data-booking-date><input type="hidden" name="route" value="booking/time"><input type="hidden" name="service_id" value="<?= $ctx['service_id'] ?>"><input type="hidden" name="employee_id" value="<?= $ctx['employee_id'] ?>"><label for="booking-date">Data</label><input id="booking-date" name="date" type="date" min="<?= e($b['today']) ?>" max="<?= e($b['max_date']) ?>" required><button class="button">Pokaż godziny</button></form><div class="slot-preview" data-slot-preview aria-live="polite"></div></section>
<?php elseif ($route === 'booking/time'): $ctx=$b['context']; ?>
<section class="page container"><?php booking_steps(4) ?><h1>Wybierz godzinę</h1><p><?= e($b['date']) ?> · <?= e($ctx['employee_name']) ?></p><div class="slot-grid" data-slots><?php if(!$b['slots']): ?><div class="empty-state">Brak wolnych terminów tego dnia.</div><?php else: foreach($b['slots'] as $slot): ?><a class="slot" href="<?= e(route_url('booking/confirm',['service_id'=>$ctx['service_id'],'employee_id'=>$ctx['employee_id'],'date'=>$b['date'],'start_time'=>$slot['start']])) ?>"><strong><?= e($slot['start']) ?></strong><span>do <?= e($slot['end']) ?></span></a><?php endforeach; endif ?></div><p><a href="<?= e(route_url('booking/date',['service_id'=>$ctx['service_id'],'employee_id'=>$ctx['employee_id']])) ?>">Zmień datę</a></p></section>
<?php elseif ($route === 'booking/confirm'): $ctx=$b['context']; ?>
<section class="page container"><?php booking_steps(5) ?><h1>Potwierdź rezerwację</h1><div class="confirm-card"><dl><div><dt>Firma</dt><dd><?= e($ctx['company_name']) ?></dd></div><div><dt>Usługa</dt><dd><?= e($ctx['service_name']) ?></dd></div><div><dt>Pracownik</dt><dd><?= e($ctx['employee_name']) ?></dd></div><div><dt>Termin</dt><dd><?= e($b['date']) ?>, <?= e($b['slot']['start']) ?>–<?= e($b['slot']['end']) ?></dd></div><div><dt>Czas i cena</dt><dd><?= (int)$ctx['duration_minutes'] ?> min · <?= e(money_pl($ctx['price'])) ?></dd></div></dl>
<form action="<?= url('booking/create') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="service_id" value="<?= $ctx['service_id'] ?>"><input type="hidden" name="employee_id" value="<?= $ctx['employee_id'] ?>"><input type="hidden" name="date" value="<?= e($b['date']) ?>"><input type="hidden" name="start_time" value="<?= e($b['slot']['start']) ?>"><input type="hidden" name="booking_token" value="<?= e($b['token']) ?>"><label for="comment">Komentarz (opcjonalnie)</label><textarea id="comment" name="comment" maxlength="1000"></textarea><button class="button full-width">Rezerwuję — termin oczekujący</button></form></div></section>
<?php elseif ($route === 'client/reservations'): $upcoming=[];$past=[];foreach($b['rows'] as $row){$when=new DateTimeImmutable($row['reservation_date'].' '.$row['end_time'],new DateTimeZone(BOOKING_TIMEZONE));if(in_array($row['status'],['pending','confirmed'],true)&&$when>booking_now())$upcoming[]=$row;else $past[]=$row;} ?>
<section class="page container"><div class="page-heading"><div><p class="eyebrow">Panel klienta</p><h1>Moje rezerwacje</h1></div><a class="button" href="<?= url('companies') ?>">Znajdź usługę</a></div><?php if(!$b['rows']): ?><div class="empty-state"><h2>Nie masz jeszcze rezerwacji</h2><p>Przejrzyj firmy i wybierz dogodny termin.</p></div><?php else: ?><h2>Nadchodzące</h2><?php if(!$upcoming): ?><p class="muted">Brak nadchodzących wizyt.</p><?php else: ?><div class="reservation-list"><?php foreach($upcoming as $row) reservation_card($row,'client/reservations/show'); ?></div><?php endif ?><h2>Historia</h2><?php if(!$past): ?><p class="muted">Historia jest pusta.</p><?php else: ?><div class="reservation-list"><?php foreach($past as $row) reservation_card($row,'client/reservations/show'); ?></div><?php endif ?><?php endif ?></section>
<?php elseif ($route === 'client/reservations/show'): $r=$b['reservation']; ?>
<section class="page container"><p class="eyebrow">Rezerwacja #<?= $r['id'] ?></p><h1><?= e($r['service_name']) ?></h1><?php require __DIR__ . '/reservation_detail.php'; ?><div class="actions"><?php $future=new DateTimeImmutable($r['reservation_date'].' '.$r['start_time'],new DateTimeZone(BOOKING_TIMEZONE)); if(in_array($r['status'],['pending','confirmed'],true)&&$future>booking_now()): ?><a class="button secondary" href="<?= e(route_url('client/reservations/reschedule',['id'=>$r['id']])) ?>">Przełóż</a><form method="post" action="<?= url('client/reservations/cancel') ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="button danger">Anuluj wizytę</button></form><?php endif ?></div></section>
<?php elseif ($route === 'client/reservations/reschedule'): $r=$b['reservation']; ?>
<section class="page container"><h1>Przełóż wizytę</h1><p><?= e($r['service_name']) ?> · <?= e($r['employee_name']) ?></p><form method="get" class="date-form"><input type="hidden" name="route" value="client/reservations/reschedule"><input type="hidden" name="id" value="<?= $r['id'] ?>"><label>Nowa data<input type="date" name="date" value="<?= e($b['date']) ?>" min="<?= e(booking_now()->format('Y-m-d')) ?>" max="<?= e(booking_now()->modify('+'.BOOKING_HORIZON_DAYS.' days')->format('Y-m-d')) ?>"></label><button class="button secondary">Pokaż godziny</button></form><form method="post" action="<?= url('client/reservations/reschedule') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="hidden" name="date" value="<?= e($b['date']) ?>"><div class="slot-grid"><?php foreach($b['slots'] as $slot): ?><label class="slot"><input type="radio" name="start_time" value="<?= e($slot['start']) ?>" required><strong><?= e($slot['start']) ?></strong><span>do <?= e($slot['end']) ?></span></label><?php endforeach ?></div><button class="button"<?= !$b['slots']?' disabled':'' ?>>Zapisz nowy termin</button></form></section>
<?php elseif ($route === 'employee/reservations'): $employee=$b['employee'];$today=[];$future=[];$history=[];foreach($b['rows'] as $row){if($row['reservation_date']===booking_now()->format('Y-m-d'))$today[]=$row;elseif(in_array($row['status'],['pending','confirmed'],true)&&$row['reservation_date']>booking_now()->format('Y-m-d'))$future[]=$row;else $history[]=$row;} ?>
<section class="page container"><div class="page-heading"><div><p class="eyebrow">Panel pracownika</p><h1>Moje wizyty · <?= e($employee['company_name']) ?></h1></div></div><?php if(count($employee['companies'])>1): ?><nav class="context-switcher"><?php foreach($employee['companies'] as $c): ?><a href="<?= e(route_url('employee/reservations',['company_id'=>$c['company_id']])) ?>"><?= e($c['company_name']) ?></a><?php endforeach ?></nav><?php endif ?><?php if(!$b['rows']): ?><div class="empty-state">Brak przypisanych wizyt.</div><?php else: ?><?php foreach(['Dzisiaj'=>$today,'Nadchodzące'=>$future,'Historia'=>$history] as $heading=>$rows): ?><h2><?= e($heading) ?></h2><?php if(!$rows): ?><p class="muted">Brak wizyt.</p><?php else: ?><div class="reservation-list"><?php foreach($rows as $row) reservation_card($row,'employee/reservations/show',['company_id'=>$employee['company_id']]); ?></div><?php endif ?><?php endforeach ?><?php endif ?></section>
<?php elseif ($route === 'employee/reservations/show'): $r=$b['reservation']; ?>
<section class="page container"><p class="eyebrow">Wizyta #<?= $r['id'] ?> · <?= e($b['employee']['company_name']) ?></p><h1><?= e($r['service_name']) ?></h1><?php require __DIR__ . '/reservation_detail.php'; ?><?php if(booking_transitions($r['status'])): ?><form class="status-form" method="post" action="<?= url('employee/reservations/status') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><input type="hidden" name="company_id" value="<?= $b['employee']['company_id'] ?>"><label>Nowy status<select name="status"><?php foreach(booking_transitions($r['status']) as $status): ?><option value="<?= e($status) ?>"><?= e(status_label($status)) ?></option><?php endforeach ?></select></label><button class="button">Zmień status</button></form><?php endif ?></section>
<?php endif ?>
